#!/usr/bin/env node
/**
 * Generate the metaclass -> rdf:type map from the vendored SysML vocabulary.
 *
 * Run at AUTHORING time, not at startup: the output is committed, so the map a
 * reviewer sees in a diff is the map that runs. Parsing the TTL at startup would
 * put 183KB and a parser on the critical path to answer a question whose answer
 * changes only when the SysML specification does.
 *
 *     node scripts/gen-sysml-types.mjs        # rewrites the generated file
 *     node scripts/gen-sysml-types.mjs --check   # fails if it is stale
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { argv, exit } from 'node:process';

const VOCAB = new URL('../vocab/SysML-vocab.ttl', import.meta.url);
const OUT = new URL('../src/adapters/rse-sysml/metaclass-types.ts', import.meta.url);
const NS = 'https://www.omg.org/spec/sysml/vocabulary#';

const ttl = readFileSync(VOCAB, 'utf8');
const classes = [...ttl.matchAll(/^oslc_sysml:(\S+) a rdfs:Class/gm)].map((m) => m[1]).sort();
if (classes.length < 100) {
  console.error(`Only ${classes.length} classes parsed from the vocabulary — refusing to write a ` +
                `map that is obviously wrong. Check the file.`);
  exit(1);
}

const body = `// GENERATED by scripts/gen-sysml-types.mjs from vocab/SysML-vocab.ttl — do not edit.
//
// ${classes.length} classes. The namespace and the subclass axiom that ties them to OSLC:
//
//     oslc_sysml:Element a rdfs:Class ; rdfs:subClassOf oslc_am:Resource .
//
// so an element's rdf:type is oslc_am:Resource plus its own metaclass. RSE's own AM surface
// already says exactly this, as ["am#Resource", "PartUsage"] — it just leaves the second a bare
// string rather than a URI.
//
// Absent deliberately: OSLCLink, which is an RSE extension rather than OMG, and which is never
// projected as a resource — it becomes a link predicate on the element that owns it.

export const SYSML_NS = '${NS}';
export const OSLC_AM_RESOURCE = 'http://open-services.net/ns/am#Resource';

const METACLASSES: ReadonlySet<string> = new Set([
${classes.map((c) => `  '${c}',`).join('\n')}
]);

/** The vocabulary URI for a metaclass, or undefined when the vocabulary does not define it. */
export function metaclassType(metaclass: string): string | undefined {
  return METACLASSES.has(metaclass) ? SYSML_NS + metaclass : undefined;
}

/**
 * The rdf:type list for an element. Always oslc_am:Resource; plus the metaclass URI when the
 * vocabulary defines one. An unknown metaclass is REPORTED rather than guessed at — minting
 * \`${NS}\` + whatever the server said would invent vocabulary, and an assistant filtering on type
 * cannot tell an invented URI from a real one.
 */
export function rdfTypes(metaclass: string | undefined): {
  types: string[]; unknownMetaclass?: string;
} {
  if (!metaclass) return { types: [OSLC_AM_RESOURCE] };
  const t = metaclassType(metaclass);
  return t
    ? { types: [OSLC_AM_RESOURCE, t] }
    : { types: [OSLC_AM_RESOURCE], unknownMetaclass: metaclass };
}

export const METACLASS_COUNT = ${classes.length};
`;

if (argv.includes('--check')) {
  const current = (() => { try { return readFileSync(OUT, 'utf8'); } catch { return ''; } })();
  if (current !== body) {
    console.error('metaclass-types.ts is stale. Run: node scripts/gen-sysml-types.mjs');
    exit(1);
  }
  console.log(`metaclass-types.ts is current (${classes.length} classes).`);
  exit(0);
}

writeFileSync(OUT, body);
console.log(`wrote ${classes.length} metaclasses to src/adapters/rse-sysml/metaclass-types.ts`);
